// План specs/technicians-sms.md 1.1–1.4 (кейсы .qa/tests/technicians-sms/TS-01…TS-04). PROD, admin, компания «test».
// @prod-safe: ничего не создаётся; SMS не уходит — service worker отключён, message-technicians перехвачен ДО перехода и Send
// (фейковый 200), send-sms/assignment-notices обрываются; тест падает, если хоть один POST ушёл в сеть (expectNothingSent).
// Без пометки устройства в 1.1 и 1.3: тикет про обрезку на десктопе 1440 и фикс для телефона — нужны все три прогона.
import { test, expect } from '@playwright/test';
import {
  ADMIN_STATE, L, Lang, TECHS,
  expectCardInside, expectNothingSent, interceptSending, openTechnicians, resultCards, sampledExtremes, selectQaTechs, sendText, startToastSampler,
} from './technicians-sms-helpers';

test.use({ storageState: ADMIN_STATE, serviceWorkers: 'block' });

async function sendAndCheckOneToast(page: import('@playwright/test').Page, guard: Awaited<ReturnType<typeof interceptSending>>, lang: Lang) {
  await openTechnicians(page, lang);
  await selectQaTechs(page, lang);
  await startToastSampler(page, lang);
  await sendText(page, lang, 'QA-AUTO de116e');

  // Тост результата: сколько отправлено и кто пропущен (источник: «מה רצוי» — לכמה טכנאים נשלח ומי דולג ולמה).
  await expect(page.getByText(L[lang].result).first()).toBeVisible({ timeout: 15_000 });
  await expect(page.getByText(L[lang].skipped).first()).toBeVisible();

  // Во время появления (≈1.2 с кадров) карточка не выходит за края.
  const anim = await sampledExtremes(page);
  expect(anim.frames, 'кадры появления записаны').toBeGreaterThan(0);
  expect(anim.minLeft, 'при появлении тост не выходит за левый край').toBeGreaterThanOrEqual(-0.5);
  expect(anim.maxRight, 'при появлении тост не выходит за правый край').toBeLessThanOrEqual(anim.innerWidth + 0.5);

  // Итоговое положение: целиком в экране, текст читается (источник: «מה רצוי» — מוצגת במלואה בתוך המסך).
  const { innerWidth, cards } = await resultCards(page, lang);
  expect(cards, 'на экране один тост результата').toHaveLength(1);
  expect(cards[0].text).toContain(TECHS.skipped);
  expectCardInside(cards[0], innerWidth);
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= document.documentElement.clientWidth + 1), 'нет горизонтальной прокрутки страницы').toBe(true);

  expectNothingSent(guard, 1);
}

test.describe('Technicians: Text selected result toast (#de116e)', () => {
  test('Text selected → Send: toast "Sent to 1 of 2 / Skipped: QA-Tech Gamma (…)" fully inside the screen, also while sliding in #de116e @prod-safe', async ({ page, context }) => {
    const guard = await interceptSending(context);
    await sendAndCheckOneToast(page, guard, 'en');
  });

  test('Two sends in a row: two result toasts stacked without overlap, both inside the screen #de116e @prod-safe', async ({ page, context }) => {
    const guard = await interceptSending(context);
    await openTechnicians(page, 'en');
    await selectQaTechs(page, 'en');
    await sendText(page, 'en', 'QA-AUTO de116e 1');
    await expect(page.getByText(L.en.result).first()).toBeVisible({ timeout: 15_000 });

    await selectQaTechs(page, 'en');
    await sendText(page, 'en', 'QA-AUTO de116e 2');
    await expect(page.getByText(L.en.result), 'два тоста результата одновременно').toHaveCount(2, { timeout: 15_000 });

    // Стопкой: прямоугольники не пересекаются, оба в экране (источник: «כמו שאר ההודעות במערכת»; #8ae966 — אחת מתחת לשנייה).
    await expect.poll(async () => {
      const { innerWidth, cards } = await resultCards(page, 'en');
      if (cards.length !== 2) return 'cards=' + cards.length;
      const [a, b] = cards;
      const yOverlap = Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top);
      const inside = cards.every((c) => c.left >= -0.5 && c.right <= innerWidth + 0.5);
      return { overlap: yOverlap > 0, inside };
    }, { message: 'два тоста стопкой без наложения, оба в экране', timeout: 5_000 }).toEqual({ overlap: false, inside: true });

    const { innerWidth, cards } = await resultCards(page, 'en');
    for (const c of cards) expectCardInside(c, innerWidth);
    expectNothingSent(guard, 2);
  });
});

test.describe('Technicians: Text selected result toast on 360px (#de116e)', () => {
  test.use({ viewport: { width: 360, height: 800 } });

  test('Phone 360px: result toast full width (16px margins), not clipped, also while sliding in #de116e @android @prod-safe', async ({ page, context }) => {
    const guard = await interceptSending(context);
    await sendAndCheckOneToast(page, guard, 'en');
  });

  test('Phone 360px HE (RTL): result toast "נשלח ל-1 מתוך 2" fully inside the screen #de116e @android @prod-safe', async ({ page, context }) => {
    const guard = await interceptSending(context);
    await sendAndCheckOneToast(page, guard, 'he');
    expect(await page.evaluate(() => document.documentElement.dir || getComputedStyle(document.body).direction)).toBe('rtl');
  });
});
